mapper.update:
UPDATE biz_license_original
license_no = #{vo.licenseNo}, config_unit_name = #{vo.configUnitName}, ownership_nature = #{vo.ownershipNature}, issuing_authority = #{vo.issuingAuthority}, unified_social_credit_code = #{vo.unifiedSocialCreditCode}, ladder_config_model = #{vo.ladderConfigModel}, issue_date = #{vo.issueDate}, legal_person = #{vo.legalPerson}, equipment_config_address = #{vo.equipmentConfigAddress}, license_device_name = #{vo.licenseDeviceName}, detailed_address = #{vo.detailedAddress},
WHERE id = #{id}

UPDATE biz_license_duplicate
production_enterprise = #{vo.productionEnterprise}, info_submit_date = #{vo.infoSubmitDate}, specific_model = #{vo.specificModel}, duplicate_issuing_authority = #{vo.duplicateIssuingAuthority}, product_serial_no = #{vo.productSerialNo}, duplicate_issue_date = #{vo.duplicateIssueDate}, installation_date = #{vo.installationDate}, original_position = #{vo.originalPosition}, remark = #{vo.remark}
WHERE id = #{vo.id}

mapper.select:
SELECT c.id as app_id, a.id as original_id, b.id as duplicate_id, a.license_no, a.config_unit_name, a.license_device_name, a.ladder_config_model, d.region, a.issue_date AS original_issuance_date, b.duplicate_issue_date AS duplicate_issue_date, c.app_type as license_type, b.acceptance_status, IF(e.application_id IS NOT NULL, 1, 0) AS is_upload from biz_license_original a left join biz_license_duplicate b on a.id = b.original_id AND b.deleted = 0 left join biz_application c on a.application_id = c.id left join biz_institution_ext d on c.institution_id = d.dept_id left join biz_acceptance_material e on c.id = e.application_id
a.deleted = 0 and c.deleted = 0
and a.application_id in (SELECT DISTINCT application_id FROM biz_acceptance_material where status = '待审核')
and c.app_type = #{p.licenseType}
and a.license_device_name = #{p.deviceType}
and a.ladder_config_model = #{p.ladderConfigModel}
and d.region = #{p.region}
and ( a.license_no like concat('%', #{p.keywords}, '%') or a.config_unit_name like concat('%', #{p.keywords}, '%') or a.license_device_name like concat('%', #{p.keywords}, '%') )
GROUP BY a.id, a.create_time order by a.create_time desc
